let avatarRuntimeV2 = null;

function escapeHtmlV2(text) {
  return String(text || "")
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&#39;");
}

function normalizeV2(text) {
  return String(text || "")
    .replace(/[，。！？；：,]/g, " ")
    .replace(/\s+/g, " ")
    .trim();
}

function dispatchAvatarEventV2(type, payload = {}) {
  if (avatarRuntimeV2 && typeof avatarRuntimeV2.dispatch === "function") {
    avatarRuntimeV2.dispatch(type, payload);
  }
}

async function ensureAvatarRuntimeV2() {
  if (avatarRuntimeV2 || typeof window.createHaiXiaoNanAvatarRuntime !== "function") return avatarRuntimeV2;
  try {
    avatarRuntimeV2 = await window.createHaiXiaoNanAvatarRuntime({
      host: elsV2.digitalHuman,
      imageUrl: "./digital-human-cutout.png"
    });
  } catch (error) {
    console.error("Avatar runtime failed to start", error);
    elsV2.digitalHuman.classList.remove("avatar-runtime-enabled");
    avatarRuntimeV2 = null;
  }
  return avatarRuntimeV2;
}

function includesAnyV2(value, list = []) {
  return list.some((item) => value.includes(normalizeV2(item)));
}

function getAgentV2(agentId) {
  return AGENT_REGISTRY_V2.find((agent) => agent.id === agentId) || null;
}

function getMetricV2(metricId) {
  return METRIC_CATALOG_V2.find((metric) => metric.id === metricId) || null;
}

function getScenarioConfigV2(id) {
  return SCENARIO_LIBRARY_V2.find((scenario) => scenario.id === id) || null;
}

function getScenarioByPromptV2(phrase) {
  const value = normalizeV2(phrase);
  return SCENARIO_LIBRARY_V2.find((scenario) => {
    if (normalizeV2(scenario.handbookPrompt || "") === value) return true;
    return (scenario.triggerPhrases || []).some((item) => normalizeV2(item) === value);
  }) || null;
}

function restingStateV2() {
  return stateV2.standbyEnabled ? "standby" : "idle";
}

function setPetStatusV2(text) {
  const next = String(text || "").trim();
  if (!next || next.includes("{commandText}")) return;
  if (
    typeof stateV2 !== "undefined" &&
    stateV2.voiceUiLockedUntil > Date.now() &&
    next !== stateV2.voiceUiStatus
  ) {
    return;
  }
  elsV2.petStatusText.textContent = next;
}

