.pet-face-overlay {
  position: absolute;
  inset: 0;
  pointer-events: none;
  z-index: 4;
  transform: translate(var(--face-x, 0px), var(--face-y, 0px));
  transition: transform 0.18s ease-out;
}

.pet-eye {
  position: absolute;
  top: 49px;
  width: 28px;
  height: 18px;
  border-radius: 14px;
  background: linear-gradient(180deg, rgba(255, 255, 255, 0.95), rgba(232, 238, 255, 0.65));
  transform: scaleY(0.08);
  transform-origin: center top;
  opacity: 0.95;
  mix-blend-mode: screen;
  box-shadow: inset 0 1px 1px rgba(0, 0, 0, 0.08);
}

.pet-eye-left {
  left: 23px;
  animation: petBlinkLeft 5.2s infinite ease-in-out;
}

.pet-eye-right {
  right: 23px;
  animation: petBlinkRight 5.2s infinite ease-in-out;
}

@keyframes petBlinkLeft {
  0%, 86%, 100% { transform: scaleY(0.08); }
  89%, 92% { transform: scaleY(0.95); }
  95% { transform: scaleY(0.2); }
}

@keyframes petBlinkRight {
  0%, 86%, 100% { transform: scaleY(0.08); }
  88.5%, 92.5% { transform: scaleY(0.95); }
  95.5% { transform: scaleY(0.18); }
}

.pet-eye-spark {
  position: absolute;
  width: 10px;
  height: 10px;
  border-radius: 999px;
  background: radial-gradient(circle, rgba(255, 255, 255, 0.92) 0%, rgba(120, 199, 255, 0.2) 65%, transparent 100%);
  animation: eyeSpark 1.7s ease-in-out infinite;
}

.pet-eye-spark-left {
  left: 39px;
  top: 53px;
}

.pet-eye-spark-right {
  right: 39px;
  top: 53px;
  animation-delay: 0.15s;
}

@keyframes eyeSpark {
  0%, 100% { opacity: 0.5; transform: scale(0.85); }
  50% { opacity: 1; transform: scale(1.15); }
}

.pet-mouth {
  position: absolute;
  left: 50%;
  top: 96px;
  width: 36px;
  height: 8px;
  border-radius: 999px;
  transform: translateX(-50%) scaleY(0.7);
  background: linear-gradient(180deg, rgba(255, 255, 255, 0.25), rgba(57, 222, 255, 0.95));
  box-shadow: 0 0 8px rgba(62, 210, 255, 0.5);
  opacity: 0.58;
  transition: transform 0.16s ease, opacity 0.16s ease, background 0.16s ease;
}

.pet.hover .pet-mouth {
  opacity: 0.75;
  transform: translateX(-50%) scaleY(0.95);
}

.pet.listening .pet-mouth,
.pet.speaking .pet-mouth {
  background: linear-gradient(180deg, rgba(255, 198, 198, 0.3), rgba(255, 92, 98, 0.95));
  animation: petTalk 0.24s ease-in-out infinite alternate;
  opacity: 1;
}

@keyframes petTalk {
  from { transform: translateX(-50%) scaleY(0.8) scaleX(0.94); }
  to { transform: translateX(-50%) scaleY(2.5) scaleX(1.06); }
}

.pet-execute-beam {
  position: absolute;
  left: 76px;
  top: 82px;
  width: 96px;
  height: 4px;
  border-radius: 999px;
  background: linear-gradient(90deg, rgba(95, 124, 255, 0), rgba(95, 124, 255, 0.92) 48%, rgba(96, 232, 255, 0.92) 100%);
