function setStateV2(state, resetAfter = 0) {
  if (state !== "dragging" && state !== "success") clearDragReleaseTimerV2();
  if (stateV2.stateTimer) {
    window.clearTimeout(stateV2.stateTimer);
    stateV2.stateTimer = null;
  }
  elsV2.digitalHuman.classList.remove("hover", "awake", "thinking", "listening", "speaking", "executing", "success", "dragging", "standby", "confirming");
  const nextState = state === "idle" ? restingStateV2() : state;
  if (nextState && nextState !== "idle") elsV2.digitalHuman.classList.add(nextState);
  syncPetStateMetaV2(nextState || "idle");
  dispatchAvatarEventV2("state", { state: nextState || "idle" });
  if (resetAfter > 0) {
    stateV2.stateTimer = window.setTimeout(() => setStateV2(restingStateV2()), resetAfter);
  }
}

function speakV2(text) {
  const content = String(text || "").trim();
  if (!content) return;
  const speechDuration = Math.min(2200, 780 + content.length * 40);
  updateVoicePresenceV2("text", "speaking", content);
  setStateV2("speaking", speechDuration);
  dispatchAvatarEventV2("speech", { text: content, duration: speechDuration });
  setPetStatusV2(content);
  if (!("speechSynthesis" in window)) return;
  try {
    window.speechSynthesis.cancel();
    const utterance = new SpeechSynthesisUtterance(content);
    utterance.lang = "zh-CN";
    utterance.rate = 1.03;
    utterance.pitch = 1.02;
    utterance.onend = () => {
      dispatchAvatarEventV2("speechEnd");
      setStateV2(restingStateV2());
    };
    utterance.onerror = () => dispatchAvatarEventV2("speechEnd");
    window.speechSynthesis.speak(utterance);
  } catch (error) {}
}

function findToolLabelV2(key) {
  return TOOL_BUTTONS_V2.find((tool) => tool.key === key)?.label || key;
}

function applyToolStateV2(toggles = []) {
  const activeSet = new Set(["freeChat", ...toggles]);
  TOOL_BUTTONS_V2.forEach((tool) => {
    TOOL_STATE_V2[tool.key] = activeSet.has(tool.key);
  });
  [...elsV2.toolRow.querySelectorAll(".tool-pill")].forEach((button) => {
    const key = button.dataset.toolKey;
    button.classList.toggle("active", TOOL_STATE_V2[key]);
    button.classList.remove("pulse");
    window.requestAnimationFrame(() => button.classList.add("pulse"));
  });
}

function positionBubbleV2() {
  const rect = elsV2.digitalHuman.getBoundingClientRect();
  const bubbleWidth = elsV2.petBubble.offsetWidth || 292;
  const leftSpace = rect.left - bubbleWidth - 16;
  elsV2.petBubble.classList.toggle("align-right", leftSpace < 12);
}

function hideBubbleV2() {
  if (stateV2.bubbleTimer) window.clearTimeout(stateV2.bubbleTimer);
  clearBubbleStreamV2();
  elsV2.digitalHuman.classList.remove("show-bubble");
}

