function bindModalV2(plan) {
  const followInput = document.getElementById("modal-follow-input-v2");
  const followSend = document.getElementById("modal-follow-send-v2");
  if (followInput && followSend) {
    followSend.addEventListener("click", () => {
      const value = followInput.value.trim();
      if (!value) return;
      handleFollowV2(plan, value);
      followInput.value = "";
    });
    followInput.addEventListener("keydown", (event) => {
      if (event.key === "Enter") {
        event.preventDefault();
        followSend.click();
      }
    });
  }
  const followMic = document.getElementById("modal-follow-mic-v2");
  if (followMic && followInput) {
    followMic.addEventListener("click", () => startModalVoiceV2(plan, followInput));
  }

  [...elsV2.modalBody.querySelectorAll(".js-suggestion-v2")].forEach((button) => {
    button.addEventListener("click", () => {
      const prompt = button.dataset.prompt;
      if (prompt === "直接展开到制度工作台") {
        const workspacePlan = { ...plan, action: "open_workspace", scriptId: null };
        openModalV2(workspacePlan, { preserveDialog: true });
        return;
      }
      const scenario = resolveRouteV2(prompt);
      if (scenario && scenario.id !== plan.route?.id) {
        processCommandV2(prompt, "suggestion");
        return;
      }
      handleFollowV2(plan, prompt);
    });
  });

  const answerExpand = document.getElementById("answer-expand-btn-v2");
  if (answerExpand) {
    answerExpand.addEventListener("click", () => {
      const workspacePlan = { ...plan, action: "open_workspace", scriptId: null };
      openModalV2(workspacePlan, { preserveDialog: true });
      toastV2("已展开到制度工作台。", "success", "智能综合");
    });
  }

  const meetingSubmit = document.getElementById("meeting-submit-btn-v2");
  const meetingDraft = document.getElementById("meeting-draft-btn-v2");

