// ─── SVG 数字人眼球跟踪 ──────────────────────────────────────────
(function() {
  var ptx = 0, pty = 0, px = 0, py = 0;
  function eyeTick() {
    px += (ptx - px) * 0.12;
    py += (pty - py) * 0.12;
    var t = 'translate(' + px.toFixed(2) + ',' + py.toFixed(2) + ')';
    var iL = document.getElementById('dh-iris-l');
    var iR = document.getElementById('dh-iris-r');
    if (iL) iL.setAttribute('transform', t);
    if (iR) iR.setAttribute('transform', t);
    requestAnimationFrame(eyeTick);
  }
  document.addEventListener('mousemove', function(e) {
    var svg = document.getElementById('dh-svg');
    if (!svg) return;
    var r = svg.getBoundingClientRect();
    var cx = r.left + r.width * 0.5;
    var cy = r.top  + r.height * 0.21;
    var dx = e.clientX - cx, dy = e.clientY - cy;
    var d  = Math.sqrt(dx * dx + dy * dy) || 1;
    var n  = Math.min(1, d / 200);
    ptx = (dx / d) * n * 2.2;
    pty = (dy / d) * n * 2.2;
  });
  requestAnimationFrame(eyeTick);
})();

