#dh-svg { display: block; width: 126px; height: 176px; overflow: visible; }
.pet.hover   #dh-svg { filter: drop-shadow(0 0 10px rgba(79,110,247,.45)); }
.pet.listening #dh-svg { filter: drop-shadow(0 0 8px rgba(255,100,108,.38)); }
.pet.speaking  #dh-svg { filter: drop-shadow(0 0 8px rgba(0,201,177,.38)); }
.pet.awake   #dh-svg { filter: drop-shadow(0 0 13px rgba(79,110,247,.55)); }
.pet.success #dh-svg { filter: drop-shadow(0 0 15px rgba(24,178,107,.55)); }
/* Eye blink */
#dh-lid-l, #dh-lid-r {
  transform-box: fill-box; transform-origin: center top; transform: scaleY(0); opacity: 0;
}
@keyframes dhBlink {
  0%,82%,100% { transform:scaleY(0.02); opacity:0; }
  86%,92%     { transform:scaleY(1);    opacity:1; }
  96%         { transform:scaleY(0.3);  opacity:1; }
}
#dh-lid-l { animation: dhBlink 5.2s ease-in-out infinite; }
#dh-lid-r { animation: dhBlink 5.2s ease-in-out infinite .09s; }
/* Mouth talking */
@keyframes dhTalk {
  from { transform: scaleY(1);   opacity: .75; }
  to   { transform: scaleY(8);   opacity: 1; }
}
.pet.speaking  #dh-mouth-open,
.pet.listening #dh-mouth-open {
  animation: dhTalk .22s ease-in-out infinite alternate;
  transform-box: fill-box; transform-origin: center;
}
.pet.speaking  #dh-smile,
.pet.listening #dh-smile { opacity: .25; }
/* Arms */
#dh-arm-l, #dh-arm-r { transform-box: fill-box; transform-origin: 50% 0%; }
@keyframes dhArmIdleL { 0%,100%{transform:translate(36px,74px) rotate(0deg)} 50%{transform:translate(36px,74px) rotate(2deg)} }
@keyframes dhArmIdleR { 0%,100%{transform:translate(90px,74px) rotate(0deg)} 50%{transform:translate(90px,74px) rotate(-2deg)} }
#dh-arm-l { transform: translate(36px,74px); animation: dhArmIdleL 4s ease-in-out infinite; }
#dh-arm-r { transform: translate(90px,74px); animation: dhArmIdleR 4s ease-in-out infinite .4s; }
@keyframes dhArmWave { 0%,100%{transform:translate(90px,74px) rotate(-5deg)} 50%{transform:translate(90px,74px) rotate(-48deg) translateY(-10px)} }
.pet.awake #dh-arm-r { animation: dhArmWave .65s ease-in-out infinite; }
@keyframes dhArmThink { 0%,100%{transform:translate(36px,74px) rotate(40deg)} 50%{transform:translate(36px,74px) rotate(34deg)} }
.pet.thinking #dh-arm-l { animation: dhArmThink 1.2s ease-in-out infinite; }
@keyframes dhArmSpeak { 0%,100%{transform:translate(90px,74px) rotate(-5deg)} 50%{transform:translate(90px,74px) rotate(-16deg)} }
.pet.speaking #dh-arm-r { animation: dhArmSpeak .6s ease-in-out infinite; }
@keyframes dhArmPoint { 0%,100%{transform:translate(90px,74px) rotate(-22deg)} 50%{transform:translate(90px,74px) rotate(-18deg)} }
.pet.executing #dh-arm-r { animation: dhArmPoint .9s ease-in-out infinite; }
@keyframes dhArmSuccessR { 0%,100%{transform:translate(90px,74px) rotate(0deg)} 35%{transform:translate(90px,74px) rotate(-55deg) translateY(-12px)} 65%{transform:translate(90px,74px) rotate(-44deg)} }
@keyframes dhArmSuccessL { 0%,100%{transform:translate(36px,74px) rotate(0deg)} 35%{transform:translate(36px,74px) rotate(55deg) translateY(-12px)} 65%{transform:translate(36px,74px) rotate(44deg)} }
.pet.success #dh-arm-r { animation: dhArmSuccessR .85s cubic-bezier(.34,1.3,.64,1); }
.pet.success #dh-arm-l { animation: dhArmSuccessL .85s cubic-bezier(.34,1.3,.64,1); }
/* Head tilt */
#dh-head { transform-box: fill-box; transform-origin: 50% 95%; }
@keyframes dhHeadThink { 0%,100%{transform:rotate(-5deg)} 50%{transform:rotate(5deg)} }
@keyframes dhHeadSpeak { 0%,100%{transform:rotate(-2deg)} 50%{transform:rotate(2deg)} }
@keyframes dhHeadAwake { 0%,100%{transform:rotate(-4deg) scale(1.02)} 50%{transform:rotate(4deg) scale(1.02)} }
.pet.thinking  #dh-head { animation: dhHeadThink 1.2s ease-in-out infinite; }
.pet.speaking  #dh-head { animation: dhHeadSpeak .7s  ease-in-out infinite; }
.pet.listening #dh-head { animation: dhHeadThink 1.0s ease-in-out infinite; }
.pet.awake     #dh-head { animation: dhHeadAwake .65s ease-in-out infinite alternate; }
/* Eyebrow raise */
@keyframes dhBrowUp { 0%,100%{transform:translateY(0)} 50%{transform:translateY(-2px)} }
.pet.awake   #dh-brow-l, .pet.awake   #dh-brow-r,
.pet.success #dh-brow-l, .pet.success #dh-brow-r { animation: dhBrowUp .5s ease-in-out infinite alternate; }
/* Sparkle twinkle */
@keyframes dhTwinkle { 0%,100%{opacity:.4;transform:scale(.8)} 50%{opacity:1;transform:scale(1.3)} }
#dh-sp1 { animation: dhTwinkle 3.2s ease-in-out infinite;      transform-box:fill-box;transform-origin:center; }
#dh-sp2 { animation: dhTwinkle 2.8s ease-in-out infinite .5s;  transform-box:fill-box;transform-origin:center; }
#dh-sp3 { animation: dhTwinkle 4s   ease-in-out infinite  1s;  transform-box:fill-box;transform-origin:center; }
#dh-sp4 { animation: dhTwinkle 3.6s ease-in-out infinite 1.5s; transform-box:fill-box;transform-origin:center; }

